// CSD_RATIONALE_BEGIN
// Strategy: GSM-Symbolic constrained decoding for single <<int(formula)>> span.
// Task guidance steers the model to emit exactly one constrained block at the end.
// Phase 0: Close any inherited open span quickly (small budget cap) so the
//          remaining budget is available for fresh reasoning + one formula span.
// Phase 1: Free unconstrained generation until "<<" is observed in the rendered
//          output or the prefix budget (78 % of maxSteps) is exhausted.
// Phase 2: If no span was opened naturally, force one with OpenConstrainedSpan.
// Phase 3: Inside the span, speculatively close on every step via CloseSpanIfComplete;
//          otherwise advance one hard-masked parser-valid token via ConstrainedStep.
// Phase 4: Fallback close over remaining budget if Phase 3 runs out before closing.
// All Dafny invariants (parser validity, length bound, cost) are maintained by
// the verified helper postconditions plus explicit step accounting.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 0 (CloseSpanWithinBudget): postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut), so invariant holds after phase 0.
//
//   Phase 1 (free loop): UnconstrainedStep does not touch parser or currentConstrainedOut.
//     When RenderedEndsWith fires we set currentConstrainedOut := []; the method
//     precondition requires parser.IsValidPrefix([]), so the invariant is restored.
//
//   Phase 2 (OpenConstrainedSpan): helper sets currentOut := [] and insideOut := true;
//     parser.IsValidPrefix([]) holds by precondition, so invariant is preserved.
//
//   Phase 3 (constrained loop):
//     CloseSpanIfComplete branch: helper postcondition gives
//       insideOut ==> parser.IsValidPrefix(currentOut) directly.
//     ConstrainedStep + AppendConstrainedToken branch: ConstrainedStep returns a
//       token that is parser-valid next or EOS; we guard with IsTokenValidNext before
//       calling AppendConstrainedToken, whose postcondition confirms
//       parser.IsValidPrefix(currentOut) after the append.
//     EOS break: insideConstrainedOut is unchanged (true), but the loop exits;
//       the existing invariant value is still parser.IsValidPrefix(currentConstrainedOut).
//
//   Phase 4 (CloseSpanWithinBudget): same postcondition as phase 0 preserves invariant.
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
//   Phase 0: steps += b0; CloseSpanWithinBudget appends at most b0 tokens, so
//     |generated| <= old_generated + b0 = |generatedPrefix| + steps.
//
//   Phase 1 (free loop): each iteration increments steps by 1 and appends at most
//     1 token (only when next != eosToken), so the bound is maintained step by step.
//
//   Phase 2 (OpenConstrainedSpan): appends exactly 1 delimiter token; steps += 1. OK.
//
//   Phase 3 (constrained loop):
//     CloseSpanIfComplete: appends at most 1 token (">>"); steps += 1. OK.
//     ConstrainedStep + IsTokenValidNext + AppendConstrainedToken: steps += 1;
//       AppendConstrainedToken appends exactly 1 token conditional on valid; net
//       visible growth <= 1 per step increment. OK.
//     EOS break: steps += 1, no token appended. OK.
//
//   Phase 4: b4 = maxSteps - steps; CloseSpanWithinBudget appends at most b4 tokens;
//     steps := maxSteps; so |generated| <= |generatedPrefix| + maxSteps. OK.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  // Base case: no budget; all out-parameters are already initialized above.
} else {
  helpers.AppendTaskGuidance(lm,
    "Solve step by step. Write final answer as <<int(formula)>>. " +
    "Formula: bare variable names (no {} braces), numbers, +,-,*,/,//,%,(,),int() only. " +
    "ONE <<int(formula)>> block only, at the very end. No LaTeX, no **, no curly braces. " +
    "Example: <<int(n_1 * price - n_2 * discount)>>");

  var steps: nat := 0;
  var prefixBudget: nat := (maxSteps * 78) / 100;

  // Phase 0: Close any inherited open span with a small budget
  if insideConstrainedOut && steps < maxSteps {
    var b0: nat := if maxSteps - steps > 30 then 30 else maxSteps - steps;
    var g0, i0, c0 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, b0
    );
    generated := g0;
    insideConstrainedOut := i0;
    currentConstrainedOut := c0;
    steps := steps + b0;
  }

  // Phase 1: Free generation until << detected or prefixBudget reached
  while steps < prefixBudget && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }

  // Phase 2: Force-open constrained span if none appeared during free generation
  if !insideConstrainedOut && steps < maxSteps {
    var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
    generated := og;
    insideConstrainedOut := oi;
    currentConstrainedOut := oc;
    steps := steps + 1;
  }

  // Phase 3: Constrained generation with per-step CloseSpanIfComplete check.
  // Close the span at the FIRST complete parse to prevent runaway generation.
  while insideConstrainedOut && steps < maxSteps
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
      if valid {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }

  // Phase 4: Fallback close with full remaining budget
  if insideConstrainedOut && steps < maxSteps {
    var b4: nat := maxSteps - steps;
    var g4, i4, c4 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, b4
    );
    generated := g4;
    insideConstrainedOut := i4;
    currentConstrainedOut := c4;
    steps := maxSteps;
  }

  cost := steps;
}
